const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const key='aitu-reference-ui-v1';
const defaults=()=>({request:{area:'Teaching methods and lesson design',goal:'I would like to make my practical classes more interactive and develop strategies for engaging students with different learning needs.',mentor:0,status:'Not started'},mentor:{name:'Aigerim S.',school:'School of Computing',expertise:'Active learning · Lesson design · Assessment',approach:'',format:'Meetings and Development Visits',capacity:'2'},plan:{status:'Draft',version:1,items:[{task:'Design an interactive practical class',note:'Active learning and differentiation',date:'2026-10-30',result:'Revised lesson plan'},{task:'Complete a Development Visit',note:'Observe, reflect and discuss',date:'2026-11-13',result:'Observation and reflection'},{task:'Review student feedback',note:'Identify improvements for the next cycle',date:'2026-12-04',result:'Agreed next steps'}],history:[]},visit:{course:'Programming Fundamentals — Practical class',date:'2026-11-13',location:'10:00 · Room 302',focus:'Student engagement, active learning and differentiation. Record specific observations and timestamps during the visit.'},assignments:{},enrollments:[],audit:[]});
let state;try{state=JSON.parse(localStorage.getItem(key))||defaults();if(!state.plan?.items)state=defaults()}catch{state=defaults()}
let model=null,modelError='',role='mentee',visitTab='preparation',ranked=state.request.skill!==undefined;
const mentors=[{name:'Aigerim S.',initials:'AS',school:'School of Computing',tags:['Active learning','Lesson design']},{name:'Daniyar N.',initials:'DN',school:'School of Engineering',tags:['Digital teaching','Assessment']},{name:'Madina K.',initials:'MK',school:'School of Computing',tags:['Action Research','Feedback']}];
const events=[{type:'WORKSHOP',title:'Make learning active',description:'Explore group activities and practical ways to engage every student.',tags:'Active learning · Lesson design'},{type:'OPEN LESSON',title:'See good teaching in action',description:'Observe a live lesson, ask questions and discuss the choices behind it.',tags:'Observation · Student engagement'},{type:'MENTOR ROUNDTABLE',title:'Turn feedback into progress',description:'Discuss classroom challenges and learn how to plan an Action Research cycle.',tags:'Feedback · Action Research'}];
const arrow='<span class="arrow" aria-hidden="true">→</span>';
const link=(text,to,secondary=false)=>`<a class="button ${secondary?'secondary':''}" href="#${to}">${text}${arrow}</a>`;
const button=(text,action,secondary=false,extra='')=>`<button type="button" class="${secondary?'secondary':''}" data-action="${action}" ${extra}>${text}${arrow}</button>`;
const field=(name,label,value='',type='text',required=true)=>`<label class="field"><span>${label}</span><input name="${name}" type="${type}" value="${esc(value)}" ${type==='search'?`placeholder="${name==='mentor-search'?'Search by name or expertise':name==='event-search'?'Search by skill or topic':'Type to search'}"`:''} ${required?'required':''}></label>`;
const area=(name,label,value='',required=true)=>`<label class="field"><span>${label}</span><textarea name="${name}" ${required?'required':''}>${esc(value)}</textarea></label>`;
const select=(name,label,options,value)=>`<label class="field"><span>${label}</span><select name="${name}">${options.map(([v,t])=>`<option value="${esc(v)}" ${String(value)===String(v)?'selected':''}>${esc(t)}</option>`).join('')}</select></label>`;
const heading=(eyebrow,title,sub)=>`<div class="page-heading"><small>${eyebrow}</small><h1>${title}</h1><p class="subtitle">${sub}</p></div>`;
function notify(message){$('#notice').textContent=message;$('#notice').style.display='block';clearTimeout(notify.timer);notify.timer=setTimeout(()=>$('#notice').style.display='none',5500)}
function save(message='Saved in this browser.'){try{localStorage.setItem(key,JSON.stringify(state));if(message)notify(message);return true}catch{notify('Browser storage is unavailable. Changes have not been saved.');return false}}
const photoObserver=new ResizeObserver(entries=>{for(const {target} of entries){const w=target.clientWidth,h=target.clientHeight,k=Math.max(w/810,h/570);target.style.backgroundSize=`${1440*k}px ${1920*k}px`;target.style.backgroundPosition=`${-630*k+(w-810*k)/2}px ${-88*k+(h-570*k)/2}px`;}});
const page=()=>location.hash.slice(1)||'landing';
function header(publicPage){return `<header><a class="brand" href="#landing" aria-label="AITU Faculty Mentoring home"><span class="logo"><img class="symbol" src="assets/logo-symbol.svg" alt=""><img class="wordmark" src="assets/logo-text.svg" alt="Astana IT University"></span><span class="brand-title">Faculty Mentoring</span></a>${publicPage?`<div class="public-nav"><a href="#about">ABOUT THE PROGRAM</a><a href="#events">EVENTS</a><button class="quiet-link language" data-action="languages">EN / KZ / RU</button>${link('Sign in','signin')}</div>`:`<div class="header-right"><button class="quiet-link" data-action="languages">EN / KZ / RU</button><button data-action="notifications">Notifications</button><span class="avatar" title="Switch demo workspace">AK<select id="role" aria-label="Demo workspace">${[['mentee','Mentee'],['mentor','Mentor'],['school','School coordinator'],['umo','Program administrator']].map(([v,t])=>`<option value="${v}" ${role===v?'selected':''}>${t}</option>`).join('')}</select></span></div>`}</header>`}
function sidebar(){let items=role==='school'?[['umo','School overview'],['requests','Requests & assignments'],['review','Plans for review'],['changes','Program changes'],['umo','School reports']]:role==='umo'?[['umo','Program overview'],['programs','Programs'],['mentors','Mentor directory'],['reports','Reports & exports'],['archive','Archive'],['settings','Program settings']]:role==='mentor'?[['overview','Overview'],['mentor-form','Mentor profile'],['programs','My mentees'],['plan','Development plans'],['visit','Meetings & visits'],['feedback','Feedback']]:[['overview','Overview'],['mentors','Find a mentor'],['request','My request'],['plan','Development plan'],['visit','Meetings & visits'],['feedback','Feedback']];return `<aside><small>WORKSPACE / ${{mentee:'MENTEE',mentor:'MENTOR',school:'SCHOOL COORDINATOR',umo:'PROGRAM ADMINISTRATOR'}[role]}</small><nav aria-label="Workspace">${items.map(([p,t])=>`<a href="#${p}" class="${page()===p?'active':''}">${t}</a>`).join('')}</nav><div class="sidebar-note"><h3>A space for growth.</h3><p>Your conversations stay<br>confidential.</p></div></aside>`}
const footer=()=>`<footer><span>AITU Faculty Mentoring</span><div class="link-row"><a href="#help">Support · Privacy · Guidelines</a><a href="#demo">Demo workspaces</a></div></footer>`;
function eventCards(){return `<div class="cards" id="event-cards">${events.map((e,i)=>`<article class="card event-card" data-event="${i}"><div class="event-photo e${i}" role="img" aria-label="${e.type.toLowerCase()} with colleagues"></div><div class="card-body"><span class="type">${e.type}</span><h2>${e.title}</h2><p>${e.description}</p><button class="profile-link" data-action="event" data-id="${i}">${e.tags}${arrow}</button></div></article>`).join('')}</div>`}
function landing(){return `<section class="landing-hero"><div class="landing-copy"><small>━ &nbsp; AITU FACULTY MENTORING</small><h1>A shared path<br>to professional<br>growth.</h1><p>Develop your teaching with a mentor. Share your experience and help a colleague grow.</p><div class="actions">${link('Create mentee form','request')}${link('Create mentor form','mentor-form',true)}</div><small>FOR AITU FACULTY / VOLUNTARY / CONFIDENTIAL</small></div><div class="photo" role="img" aria-label="Astana campus and city"></div></section><section class="landing-band"><h2>Not sure which skill<br>to develop?</h2><div><p>Start with an event. Join a workshop or an open lesson, meet mentors and discover what you would like to learn next.</p>${link('Explore events','events')} &nbsp; Learn before you choose.</div></section><section class="public-section"><small>DISCOVER SKILLS THROUGH SHARED PRACTICE</small><div class="section-heading"><h2 style="font-size:40px">Learn with our mentors</h2>${link('View all events','events',true)}</div>${eventCards()}<p class="demo-note">Illustrative events for the prototype. Dates and mentors will be confirmed by AITU.</p><hr><h2 style="font-size:40px">Your next step starts here.</h2><div class="grid3">${[['Share your goals','Create your mentee form and tell us what you want to develop.','request'],['Find your mentor','Explore expertise and agree the right support together.','mentors'],['Put learning into practice','Build a plan, meet, observe and reflect on your progress.','plan']].map(([t,d,p],i)=>`<a class="journey-card" style="border:0;padding-left:0" href="#${p}"><small>0${i+1} / MENTORING</small><h2>${t}</h2><p>${d}</p></a>`).join('')}</div></section><footer class="landing-footer"><h3>AITU Faculty Mentoring</h3><a href="#help">Support · Privacy · Program guidelines</a></footer>`}
function eventPage(){return `<section class="public-section">${heading('WORKSHOPS / OPEN LESSONS / SHARED PRACTICE','Explore skills with mentors','Experience new approaches before choosing your development focus. Learn with AITU colleagues through practical events.')}<div class="filter-row">${field('event-search','Find an event','','search',false)}${select('event-format','Event format',[['','All formats'],...events.map(e=>[e.type,e.type])],'')}${select('event-skill','Skill area',[['','All skills'],['Active learning','Active learning'],['Observation','Observation'],['Feedback','Feedback']],'')}</div>${eventCards()}<p id="event-empty" hidden>No events match your filters.</p><p class="demo-note">Illustrative events for the prototype. Dates and mentors will be confirmed by AITU.</p><div class="blue row public-cta"><h2>Found a skill you want to develop?</h2><div class="actions">${link('Create mentee form','request')}${link('Create mentor form','mentor-form',true)}</div></div></section>${footer()}`}
function signin(){return `<section class="signin"><div class="photo signin-photo"><div class="signin-quote"><h2>Support starts<br>with a conversation.</h2><p>A shared commitment to better teaching.</p></div></div><form class="signin-form" data-form="signin"><small>WELCOME BACK</small><h1>Your next chapter<br>starts here.</h1><p class="subtitle">Sign in to your AITU mentoring workspace.</p>${field('email','Corporate email','name@astanait.edu.kz','email')}${field('password','Password','','password')}<div style="text-align:right"><button type="button" class="quiet-link" data-action="forgot">Forgot password?</button></div><button type="submit">Sign in${arrow}</button><p class="helper">Demo access only. No account is authenticated and no password is stored or sent. Use an illustrative email and password.</p><p class="demo-note" style="margin-top:65px">Need help? Contact the program administrator.</p></form></section>`}
function overview(){return `${heading('MY WORKSPACE','Your mentoring journey','A clear view of your goals, conversations and next steps.')}<div class="overview-banner"><div><small>YOUR NEXT STEP</small><h2>Start with what matters to you.</h2><p>Tell us where you would like support, then explore colleagues who can help.</p>${link('Create a request','request')}</div><div class="photo" role="img" aria-label="Astana campus"></div></div><div class="grid3">${[['Find a mentor','Explore expertise across AITU.','mentors'],['Build your plan','Turn your goals into practical steps.','plan'],['Reflect & develop','Learn from visits and feedback.','visit']].map(([t,d,p],i)=>`<a class="journey-card" href="#${p}"><small>0${i+1} / YOUR JOURNEY</small><h2>${t}</h2><p>${d}</p></a>`).join('')}</div><h2 class="section-title">Program at a glance</h2><div class="grid3">${[['CURRENT STATUS',state.request.status],['MENTOR',state.request.status==='Not started'?'Not assigned':`${mentors[state.request.mentor]?.name||'Not selected'} (preferred)`],['DEVELOPMENT PLAN',state.plan.status==='Draft'?'Ready when you are':state.plan.status]].map(([t,v])=>`<div class="glance"><small>${t}</small><p>${esc(v)}</p></div>`).join('')}</div>`}
function matchingFields(){if(!model)return `<p class="loading">${modelError||'Loading the open-data matching model…'}</p>`;return `<details class="matching-box" ${state.request.skill!==undefined?'open':''}><summary>Find recommendations by skill</summary><p class="helper">Choose a skill from the open UniSkill dataset to explore courses and linked demo mentors.</p>${field('skill-search','Search available skills','','search',false)}${select('skill','Development skill',model.skills.map(s=>[s.id,s.label]),state.request.skill??model.skills[0].id)}<p id="skill-description" class="helper skill-description"></p>${button('Find recommended mentors','recommend')}<p class="helper">Recommendations use course–skill relevance. Your written goals provide context and are not scored.</p></details>`}
function request(){return `${heading('START YOUR PROGRAM','Your professional request','A thoughtful starting point helps you find a mentor and set useful goals.')}<div class="columns"><form class="panel" data-form="request"><small>01 / YOUR DEVELOPMENT GOALS</small>${field('area','Area of support',state.request.area)}${area('goal','What would you like to work on?',state.request.goal)}${select('mentor','Preferred mentor',[['','Help me choose'],...mentors.map((m,i)=>[i,`${m.name} — ${m.school}`])],state.request.mentor)}<p class="helper">A preference does not confirm an assignment.</p><div class="actions"><button type="submit">Submit request${arrow}</button>${button('Save draft','request-draft',true)}</div>${matchingFields()}</form><div><div class="blue steps"><small>WHAT HAPPENS NEXT</small><p><b>01</b> School review</p><div class="helper">Your request is reviewed by your School.</div><p><b>02</b> Mutual agreement</p><div class="helper">Availability and consent are confirmed.</div><p><b>03</b> Start planning</p><div class="helper">Build your plan after the assignment.</div></div><div class="side-copy"><h2>Your growth, your direction.</h2><p>Mentoring supports professional development. It is not an appraisal or ranking process.</p></div></div></div>`}
function mentorForm(){const m=state.mentor;return `${heading('JOIN AS A MENTOR','Share your expertise','Tell colleagues what you can help with and how you prefer to work together.')}<div class="columns"><form class="panel" data-form="mentor"><small>YOUR MENTOR PROFILE</small><div class="field-grid">${field('name','Full name',m.name)}${field('school','School',m.school)}</div>${field('expertise','Areas of expertise',m.expertise)}${area('approach','Your experience and approach',m.approach)}<div class="field-grid">${field('format','Preferred format',m.format)}${select('capacity','Available capacity',[[1,'Up to 1 active mentee'],[2,'Up to 2 active mentees']],m.capacity)}</div><div class="actions"><button type="submit">Submit mentor form${arrow}</button>${button('Save draft','mentor-draft',true)}</div></form><div><div class="blue" style="min-height:300px"><small>MENTORING AT AITU</small><h2>Experience worth sharing.</h2><p>Your School reviews the profile before it appears in the mentor directory. Assignments are agreed with both participants.</p></div><div class="side-copy"><h2>Help someone take<br>their next step.</h2><p>Mentoring is voluntary, confidential and focused on professional growth.</p></div></div></div>`}
function owner(c){return Object.hasOwn(state.assignments,c.id)?Number(state.assignments[c.id]):c.mentor}
function ranking(){const s=model?.skills.find(s=>s.id===Number(state.request.skill));return mentors.map((m,id)=>{let best=null;if(s)for(const c of model.courses){if(owner(c)!==id)continue;const result=Matching.score(model,s,c);if(!best||result.probability>best.probability)best={...result,course:c}}return {...m,id,best}}).sort((a,b)=>ranked?(b.best?.probability??-1)-(a.best?.probability??-1):a.id-b.id)}
function mentorPage(){return `${heading('MENTOR DIRECTORY','Find the right support','Explore colleagues by expertise, School and the professional questions you want to work on.')}<div class="filter-row">${field('mentor-search','Search','','search',false)}${select('school','School',[['','All Schools'],['School of Computing','School of Computing'],['School of Engineering','School of Engineering']],'')}${select('expertise','Expertise',[['','All areas'],...mentors.flatMap(m=>m.tags).map(t=>[t,t])],'')}</div>${ranked?`<div class="summary">Development focus: ${esc(model?.skills.find(s=>s.id===Number(state.request.skill))?.label||'Loading…')} <a href="#request">Change skill →</a><p class="helper">Course relevance scores; not a validated measure of mentor suitability.</p></div>`:''}<div class="section-heading"><h2>Available mentors</h2><span id="mentor-count"></span></div><div class="cards" id="mentor-cards"></div><p class="demo-note">Profiles shown are illustrative prototype data.</p><div class="link-row"><a href="#request">Find recommendations by skill →</a><a href="#courses">Manage demo course assignments →</a><a href="#model">About the matching model →</a></div>`}
function renderMentors(){const q=($('[name=mentor-search]')?.value||'').toLowerCase(),school=$('[name=school]')?.value,expertise=$('[name=expertise]')?.value;const list=ranking().filter(m=>(!school||m.school===school)&&(!expertise||m.tags.includes(expertise))&&`${m.name} ${m.tags.join(' ')} ${m.best?.course.title||''}`.toLowerCase().includes(q));$('#mentor-count').textContent=`${list.length} mentors shown`;$('#mentor-cards').innerHTML=list.map(m=>`<article class="card"><div class="card-top"><span class="initials">${m.initials}</span><span class="badge">Available</span></div><div class="card-body"><h2>${m.name}</h2><p class="school">${m.school}</p><div class="tags">${m.tags.map(t=>`<span class="tag">${t}</span>`).join('')}</div>${ranked?(m.best?`<p class="score">${m.best.match?'Matching course found':'Below matching threshold'} · ${(m.best.probability*100).toFixed(1)}%</p><div class="bar"><i style="width:${m.best.probability*100}%"></i></div><p class="course-title">${esc(m.best.course.title)}</p>${button('View course evidence','evidence',true,`data-id="${m.id}"`)}`:'<p>No courses linked to this profile.</p>'):''}<button class="profile-link" data-action="profile" data-id="${m.id}">View mentor profile${arrow}</button></div></article>`).join('')||'<p>No mentors meet these filters.</p>'}
function plan(){return `${heading('MY PROGRAM / INDIVIDUAL PLAN','Your development plan','Agree meaningful goals with your mentor and turn them into achievable activities.')}<div class="blue grid3 plan-summary"><div><small>MENTOR</small><h3>${mentors[state.request.mentor]?.name||'Not selected'} <small>(illustrative)</small></h3></div><div><small>PROGRAM PERIOD</small><p>October — December 2026</p></div><div><small>PLAN VERSION</small><p>Version ${state.plan.version} · ${esc(state.plan.status)}</p></div></div><div class="section-heading"><h2>Goals, activities and milestones</h2>${button('Add activity','add-activity',true)}</div><div class="table-wrap"><table><thead><tr><th>ACTIVITY</th><th>TARGET DATE</th><th>EXPECTED RESULT</th></tr></thead><tbody>${state.plan.items.map((v,i)=>`<tr><td>0${i+1} &nbsp;&nbsp; ${esc(v.task)}<span class="helper">&emsp;&emsp; ${esc(v.note)}</span></td><td>${esc(v.date)}</td><td class="helper">${esc(v.result)}</td></tr>`).join('')}</tbody></table></div><div class="row bottom-actions"><p class="helper">Plans are approved by the School Director.</p><div class="actions">${button('Save draft','plan-draft',true)}${button('Submit for approval','plan-submit')}</div></div>${state.plan.comment?`<p class="notification">School feedback: ${esc(state.plan.comment)}</p>`:''}<p class="demo-note">Illustrative plan workflow. <a href="workflow.html">Open the complete appointment and mutual-consent scenario</a>.</p>${state.plan.history.length?`<details><summary>Version history (${state.plan.history.length})</summary>${state.plan.history.map(h=>`<p>Version ${h.version} · ${esc(h.status)} · ${h.items.length} activities</p>`).join('')}</details>`:''}`}
function visit(){const v=state.visit;return `${heading('SHARED PRACTICE / DEVELOPMENT VISIT','Observe. Reflect. Develop.','A supportive lesson observation, guided by the goals you agree with your mentor.')}<div class="tabs">${['preparation','observation','reflection'].map((t,i)=>`<button class="${visitTab===t?'active':''}" data-action="visit-tab" data-tab="${t}">0${i+1} ${t.toUpperCase()}</button>`).join('')}</div><div class="columns"><form class="panel" data-form="visit"><h2>${{preparation:'Prepare your visit',observation:'Record your observations',reflection:'Reflect together'}[visitTab]}</h2>${visitTab==='preparation'?`${field('course','Course / lesson',v.course)}<div class="field-grid">${field('date','Date',v.date,'date')}${field('location','Time / location',v.location)}</div>${area('focus','Agreed observation focus',v.focus)}`:visitTab==='observation'?`${field('timestamp','Observation time (mm:ss)',v.timestamp||'10:00')}${area('observation','Observed teacher and student actions',v.observation||'')}`:`${area('plus','Plus — strengths',v.plus||'')}${area('question','Question for discussion',v.question||'')}${area('recommendation','Recommendation and next step',v.recommendation||'')}`}<div class="actions"><button type="submit">Save ${visitTab}${arrow}</button>${visitTab==='preparation'?button('Observation form','visit-tab',true,'data-tab="observation"'):''}</div></form><div><div class="photo" role="img" aria-label="Astana campus"></div><div class="side-copy" style="padding:30px 26px"><small>A SHARED APPROACH</small><h2 style="margin-top:20px">Plus. Question.<br>Recommendation.</h2><p>Notice strengths. Ask thoughtful questions. Agree a practical next step together.</p></div></div></div>`}
function review(){return `${heading('SCHOOL WORKSPACE / REVIEW','Support the next step','Review requests and plans for your School, with clear decisions and helpful feedback.')}<div class="blue row" style="margin-bottom:30px"><div><small>PENDING REVIEW</small><h3 style="margin-top:12px">Individual development plan</h3></div><span class="badge">${esc(state.plan.status)}</span></div><div class="columns"><div class="panel review-summary"><h2>Plan summary</h2><small>MENTEE</small><p>Alina K. · School of Computing</p><small>MENTOR</small><p>${mentors[state.request.mentor]?.name||'Not selected'} · School of Computing</p><small>DEVELOPMENT FOCUS</small><p>${esc(state.request.area)}</p><hr><a class="profile-link" href="#plan">View full plan and version history →</a></div><form class="panel" data-form="review"><small>YOUR DECISION</small><h2>Keep progress moving.</h2>${area('comment','Review comment',state.plan.comment||'',false)}<p class="helper">A comment is required when returning a plan for revision.</p><div class="review-buttons"><button type="submit" name="decision" value="Approved" ${state.plan.status!=='Needs review'?'disabled':''}>Approve plan${arrow}</button><button class="secondary" type="submit" name="decision" value="Returned for revision" ${state.plan.status!=='Needs review'?'disabled':''}>Return for revision${arrow}</button></div></form></div><p class="helper" style="margin-top:32px">Demo School workspace. Submit a plan before reviewing it.</p>`}
const programs=()=>[{name:'Alina K. / '+(mentors[state.request.mentor]?.name||'Not selected'),school:'Computing',status:state.plan.status,docs:state.plan.status==='Approved'?'5 of 5':'4 of 5'},{name:'Timur A. / Daniyar N.',school:'Engineering',status:'Active',docs:'5 of 5'},{name:'Dana M. / Madina K.',school:'Computing',status:'Final review',docs:'7 of 8'}];
function programTable(){return `<div class="table-wrap"><table><thead><tr><th>PROGRAM</th><th>SCHOOL</th><th>STATUS</th><th>DOCUMENTS</th></tr></thead><tbody>${programs().map(p=>`<tr><td>${esc(p.name)}</td><td class="helper">${p.school}</td><td><span class="badge">${esc(p.status)}</span></td><td>${p.docs}</td></tr>`).join('')}</tbody></table></div>`}
function umo(){return `${heading('UNIVERSITY WORKSPACE / PROGRAM ADMINISTRATION','A clear view of the program','Monitor participation, document completeness and progress across AITU.')}<div class="grid3">${[['ACTIVE PROGRAMS',24+(state.plan.status==='Approved'?1:0)],['AWAITING APPROVAL',6+(state.plan.status==='Needs review'?1:0)],['COMPLETED PROGRAMS',18]].map(([t,v])=>`<div class="stats-card"><small>${t}</small><strong>${String(v).padStart(2,'0')}</strong></div>`).join('')}</div><div class="section-heading"><h2>Programs requiring attention</h2><a href="#programs">View all programs →</a></div>${programTable()}<div class="blue row report-banner"><p>Reports include authorized program data. Confidential consultation details are excluded.</p>${button('Export report','export')}</div><p class="demo-note">Illustrative prototype data · Export activity is recorded in the local audit log.</p>`}
function courses(){return `${heading('MATCHING DEMONSTRATION','Mentor courses','Manage the illustrative course links used to rank demo mentors.')}<p class="helper">Initial assignments use course index modulo 3. They are not verified teaching records.</p>${select('course-mentor','Mentor',mentors.map((m,i)=>[i,m.name]),0)}${field('course-search','Find a course','','search',false)}<div id="course-list"></div>${button('Reset demo assignments','reset-courses',true)}`}
function renderCourses(){if(!model){$('#course-list').textContent=modelError||'Loading courses…';return}const id=Number($('[name=course-mentor]').value),q=$('[name=course-search]').value.toLowerCase();$('#course-list').innerHTML=model.courses.filter(c=>c.title.toLowerCase().includes(q)).map(c=>`<label class="course-option"><input type="checkbox" data-course="${c.id}" ${owner(c)===id?'checked':''}><span>${esc(c.title)}<br><small>${owner(c)>=0?'Linked to '+mentors[owner(c)]?.name:'Unassigned'}</small></span></label>`).join('')||'No courses found.'}
function modelPage(){return `${heading('OPEN DATA / LOGISTIC REGRESSION','How recommendations work','A reproducible course–skill matching demonstration using UniSkill.')}<div class="panel"><h2>Why open data?</h2><p>Confidential university data was not provided for training or demonstration. This project therefore uses the publicly available <a href="https://huggingface.co/datasets/nurlanm/UniSkill_dataset">UniSkill dataset</a> (Apache-2.0), with illustrative mentor profiles.</p><p>Five lexical features compare a selected skill with a course title and content. The fitted StandardScaler and logistic regression coefficients produce a course relevance score. Each demo mentor is ranked by their highest-scoring linked course.</p><p>Free-text goals are saved as context, not used as model inputs. Scores do not measure a person's competence or establish an assignment.</p></div><div class="metrics" style="margin-top:28px">${[['Held-out test accuracy','72.69%'],['Test Macro-F1','0.6938'],['Decision threshold','0.55']].map(([t,v])=>`<div class="metric">${t}<strong>${v}</strong></div>`).join('')}</div><p class="helper">216 test course–skill pairs. These metrics are from the supplied experiment, not an evaluation of mentor suitability or results at AITU. Lexical overlap can produce unsuitable recommendations.</p><p><a href="https://aclanthology.org/2026.lrec-1.31/">Musazade, Mezei & Zhang (2026). UniSkill.</a></p>`}
function extra(p){if(p==='demo')return `${heading('INTERACTIVE PROTOTYPE','Explore the workspaces','Choose a demo role. Data is stored only in this browser.')}<div class="grid3">${[['Mentee','overview'],['Mentor','mentor-form'],['School review','review'],['Program administrator','umo'],['Matching model','model']].map(([t,p])=>link(t,p,true)).join('')}</div><p class="helper">Role switching is for demonstrations and is not authentication.</p><p><a href="workflow.html">Complete appointment, consent and program workflow →</a></p>`;
if(p==='feedback')return `${heading('REFLECTION / FEEDBACK','Keep learning together','Record your reflection on the mentoring experience.')}<form class="panel" data-form="feedback">${area('feedback','Your reflection',state.feedback||'')}<button type="submit">Save feedback${arrow}</button></form>`;
if(['programs','reports','archive'].includes(p))return `${heading('PROGRAM ADMINISTRATION',p==='archive'?'Program archive':'Programs and reports','Illustrative records for this prototype.')} ${p==='archive'?'<p>No completed records in the local demonstration.</p>':programTable()}<div class="actions">${button('Export report','export')}</div>`;
if(p==='requests')return `${heading('SCHOOL WORKSPACE','Requests & assignments','Review the local demonstration request.')}<div class="panel"><h2>Alina K.</h2><p>${esc(state.request.area)}</p><span class="badge">${esc(state.request.status)}</span><p>Preferred mentor: ${mentors[state.request.mentor]?.name||'Not selected'}</p><a href="workflow.html">Continue the full appointment and consent scenario →</a></div>`;
if(p==='changes')return `${heading('PROGRAM CHANGES','Request a change','Record a reason for the School to review.')}<form class="panel" data-form="change">${area('change','Reason for change',state.change||'')}<button type="submit">Save change request${arrow}</button></form>`;
if(p==='settings')return `${heading('PROGRAM SETTINGS','Demo settings','Manage course assignments and inspect the local audit log.')}<p><a href="#courses">Mentor course assignments →</a></p><div class="panel">${state.audit.map(a=>`<p>${esc(a.at)} · ${esc(a.action)}</p>`).join('')||'No actions recorded yet.'}</div>`;
return `${heading('AITU FACULTY MENTORING',p==='about'?'A shared commitment to better teaching.':'Support, privacy and guidelines','Voluntary mentoring for professional growth.')}<div class="panel"><h2>A space for development</h2><p>Share your goals, explore mentors, agree a plan and learn through practice and reflection.</p><p>This local prototype uses illustrative profiles and public course–skill data. Drafts remain in your browser. It does not provide institutional authentication, shared storage or production access controls.</p>${link('Explore the workspaces','demo')} <a href="#model">About the open-data model</a></div>`}
function render(){photoObserver.disconnect();const p=page();if(p==='mentor-form')role='mentor';if(p==='review'||p==='requests')role='school';if(p==='umo'||p==='settings')role='umo';if(p==='request')role='mentee';const publicPage=['landing','signin','events','about'].includes(p);const views={landing,signin,events:eventPage,overview,request,'mentor-form':mentorForm,mentors:mentorPage,plan,visit,review,umo,courses,model:modelPage};const body=(views[p]||(()=>extra(p)))();$('#app').innerHTML=header(publicPage)+(publicPage?`<main class="public-main">${body}</main>`:`<div class="layout workspace">${sidebar()}<main><div class="content">${body}</div>${footer()}</main></div>`);document.querySelectorAll('.photo').forEach(el=>photoObserver.observe(el));if(p==='mentors')renderMentors();if(p==='courses')renderCourses();if(p==='request')describeSkill();document.title=`${({landing:'Faculty Mentoring',request:'Mentee form','mentor-form':'Mentor form',mentors:'Mentor catalogue',umo:'UMO overview',review:'School review',plan:'Development plan',visit:'Development Visit'}[p]||p[0].toUpperCase()+p.slice(1))} · AITU`}
function describeSkill(){const s=model?.skills.find(s=>s.id===Number($('[name=skill]')?.value));if($('#skill-description'))$('#skill-description').textContent=s?.description||'Select a skill from UniSkill.'}
function modal(html){$('#dialog-body').innerHTML=html;$('#dialog').showModal()}
function collectRequest(){const f=$('[data-form=request]');if(!f)return;const d=Object.fromEntries(new FormData(f));state.request={...state.request,area:d.area,goal:d.goal,mentor:d.mentor===''?'':Number(d.mentor),...(d.skill!==undefined?{skill:Number(d.skill)}:{})}}
function audit(action){state.audit.push({action,at:new Date().toISOString()})}
function filterEvents(){const q=($('[name=event-search]')?.value||'').toLowerCase(),f=$('[name=event-format]')?.value,s=$('[name=event-skill]')?.value;let count=0;document.querySelectorAll('[data-event]').forEach(el=>{const e=events[Number(el.dataset.event)],show=(!q||`${e.title} ${e.tags} ${e.description}`.toLowerCase().includes(q))&&(!f||e.type===f)&&(!s||e.tags.includes(s));el.hidden=!show;count+=Number(show)});if($('#event-empty'))$('#event-empty').hidden=count>0}
$('#close-dialog').onclick=()=>$('#dialog').close();
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0)});
document.addEventListener('input',e=>{const n=e.target.name;if(n==='mentor-search')renderMentors();if(n==='event-search')filterEvents();if(n==='course-search')renderCourses();if(n==='skill-search'&&model){const q=e.target.value.toLowerCase(),previous=$('[name=skill]').value,list=model.skills.filter(s=>s.label.toLowerCase().includes(q));$('[name=skill]').innerHTML=list.map(s=>`<option value="${s.id}">${esc(s.label)}</option>`).join('');if(list.some(s=>String(s.id)===previous))$('[name=skill]').value=previous;$('[data-action=recommend]').disabled=!list.length;describeSkill()}});
document.addEventListener('change',e=>{const n=e.target.name;if(e.target.id==='role'){role=e.target.value;location.hash={mentee:'overview',mentor:'mentor-form',school:'review',umo:'umo'}[role];render()}if(['school','expertise'].includes(n))renderMentors();if(['event-format','event-skill'].includes(n))filterEvents();if(n==='skill')describeSkill();if(n==='course-mentor')renderCourses();if(e.target.dataset.course){state.assignments[e.target.dataset.course]=e.target.checked?Number($('[name=course-mentor]').value):-1;save('Course assignment saved.');renderCourses()}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action,id=Number(b.dataset.id);
if(action==='languages')modal('<h2>Language availability</h2><p>These reference screens are implemented in English. The original workflow demonstration is available in Russian.</p><a href="workflow.html">Открыть сценарии на русском →</a>');
if(action==='notifications')modal(`<h2>Notifications</h2><p>Request: ${esc(state.request.status)}</p><p>Plan: ${esc(state.plan.status)}</p><p class="helper">Local demo activity only.</p>`);
if(action==='forgot')modal('<h2>Account support</h2><p>This is a local demo; no account or password has been created. For institutional access, contact the program administrator.</p>');
if(action==='request-draft'){collectRequest();state.request.status='Draft';save('Request draft saved.')}
if(action==='mentor-draft'){state.mentor={...state.mentor,...Object.fromEntries(new FormData($('[data-form=mentor]')))};save('Mentor profile draft saved.')}
if(action==='recommend'){collectRequest();if(!model?.skills.some(s=>s.id===state.request.skill)){notify('Select an available skill.');return}if(save('Recommendations calculated from the selected skill.')){ranked=true;location.hash='mentors'}}
if(action==='profile'){const m=mentors[id];modal(`<small>MENTOR PROFILE · ILLUSTRATIVE DATA</small><h2>${m.name}</h2><p>${m.school}</p><p>${m.tags.join(' · ')}</p><p>Available for meetings and Development Visits. The School confirms availability and mutual agreement before assignment.</p>${button('Choose preferred mentor','choose',false,`data-id="${id}"`)}`)}
if(action==='choose'){state.request.mentor=id;if(save('Preferred mentor saved. This does not confirm an assignment.')){$('#dialog').close();location.hash='request'}}
if(action==='evidence'){const m=ranking().find(m=>m.id===id),v=m?.best;if(!v)return;modal(`<small>COURSE EVIDENCE</small><h2>${esc(v.course.title)}</h2><p>${esc(v.course.content)}</p><table>${v.features.map((x,i)=>`<tr><td>${['Content–skill cosine','Title–skill cosine','Minimum cosine','Content–skill Jaccard','Title–skill Jaccard'][i]}</td><td>${x.toFixed(6)}</td></tr>`).join('')}</table><p>Model score: ${v.probability.toFixed(6)} · Threshold: ${model.threshold.toFixed(2)}</p><p class="helper">This course is illustratively assigned to ${m.name}. The score is not a validated measure of mentor suitability.</p>`)}
if(action==='add-activity')modal(`<h2>Add an activity</h2><form class="dialog-form" data-form="activity">${field('task','Activity')}${field('note','Development focus')}${field('date','Target date','2026-11-20','date')}${field('result','Expected result')}<button type="submit">Add activity${arrow}</button></form>`);
if(action==='plan-draft'){if(['Approved','Needs review'].includes(state.plan.status)){state.plan.history.push(structuredClone({...state.plan,history:undefined}));state.plan.version++}state.plan.status='Draft';save('Plan draft saved.');render()}
if(action==='plan-submit'){if(!state.plan.items.length){notify('Add at least one activity.');return}state.plan.status='Needs review';audit('Plan submitted for demo School review');save('Plan submitted. Open the School workspace to review it.');render()}
if(action==='visit-tab'){const form=$('[data-form=visit]');if(form){Object.assign(state.visit,Object.fromEntries(new FormData(form)));save('')}visitTab=b.dataset.tab;render()}
if(action==='reset-courses'){state.assignments={};save('Illustrative assignments restored.');renderCourses()}
if(action==='event'){const v=events[id];modal(`<small>${v.type}</small><h2>${v.title}</h2><p>${v.description}</p><p>Dates and mentors will be confirmed by AITU.</p><p class="helper">Registering interest is saved in this browser only.</p>${button(state.enrollments.includes(id)?'Interest registered':'Register interest','enroll',false,`data-id="${id}" ${state.enrollments.includes(id)?'disabled':''}`)}`)}
if(action==='enroll'){if(!state.enrollments.includes(id))state.enrollments.push(id);if(save('Your interest has been saved locally.'))$('#dialog').close()}
if(action==='export'){const rows=[['Program','School','Status','Documents'],...programs().map(p=>[p.name,p.school,p.status,p.docs])];const csv='\uFEFF'+rows.map(r=>r.map(v=>'"'+String(v).replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='aitu-program-report.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);audit('Exported administrative demo summary (no private visit notes)');save('Report exported. Local audit entry recorded.')}
});
document.addEventListener('submit',e=>{const f=e.target;if(!f.dataset.form)return;e.preventDefault();const data=Object.fromEntries(new FormData(f));switch(f.dataset.form){case 'signin':role='mentee';location.hash='overview';notify('Demo workspace opened. No password was stored or sent.');break;case 'request':collectRequest();state.request.status='Submitted for School review';audit('Request submitted');save('Request submitted in the local demo.');location.hash='overview';break;case 'mentor':state.mentor={...data,status:'Submitted for School review'};audit('Mentor profile submitted');save('Profile submitted for demo School review.');break;case 'activity':if(data.date<'2026-10-01'||data.date>'2026-12-31'){notify('Choose a date within October–December 2026.');return}state.plan.history.push(structuredClone({...state.plan,history:undefined}));state.plan.version++;state.plan.items.push(data);state.plan.status='Draft';save('Activity added. The updated plan requires a new review.');$('#dialog').close();render();break;case 'visit':if(visitTab==='observation'&&!/^\d{1,3}:[0-5]\d$/.test(data.timestamp)){notify('Use mm:ss for the observation time.');return}if(visitTab==='reflection'&&!state.visit.observation){notify('Save an observation before completing the reflection.');return}Object.assign(state.visit,data);save(`${visitTab[0].toUpperCase()+visitTab.slice(1)} saved in this browser.`);break;case 'review':{if(state.plan.status!=='Needs review')return;const decision=e.submitter?.value;if(decision==='Returned for revision'&&!data.comment.trim()){notify('Add a helpful comment before returning the plan.');return}state.plan.status=decision;state.plan.comment=data.comment;audit('Plan '+decision);save('School decision saved.');render();break}case 'feedback':state.feedback=data.feedback;save('Feedback saved locally.');break;case 'change':state.change=data.change;audit('Change request saved');save('Change request saved locally.');break}});
render();
fetch('matching/model.json').then(r=>{if(!r.ok)throw Error('HTTP '+r.status);return r.json()}).then(m=>{if(!m.skills?.length||!m.courses?.length||m.coef?.length!==5)throw Error('Invalid model');model=m;if(['request','mentors','courses'].includes(page()))render()}).catch(e=>{modelError='The matching model could not be loaded. Reload to try again.';console.error(e);if(['request','courses'].includes(page()))render()});
